const owner = String(input.owner || '').trim();
const repo = String(input.repo || '').trim();
const number = Math.max(1, Math.floor(Number(input.number) || 0));
const limit = Math.max(1, Math.min(Number(input.limit) || 15, 30));
const basePath = '/repos/' + encodeURIComponent(owner) + '/' + encodeURIComponent(repo) + '/issues/' + number;
const issueUrl = new URL(basePath, 'https://api.github.com').href;
const commentsUrl = new URL(basePath + '/comments?per_page=' + limit, 'https://api.github.com').href;
const [issueRes, commentsRes] = await Promise.all([
  fetch(issueUrl, { credentials: 'omit', headers: { Accept: 'application/vnd.github+json' } }),
  fetch(commentsUrl, { credentials: 'omit', headers: { Accept: 'application/vnd.github+json' } })
]);
const classifyAccessError = async (res, fallbackUrl) => {
  const remaining = res.headers && typeof res.headers.get === 'function' ? res.headers.get('x-ratelimit-remaining') : null;
  const reset = res.headers && typeof res.headers.get === 'function' ? res.headers.get('x-ratelimit-reset') : null;
  const retryAfter = res.headers && typeof res.headers.get === 'function' ? res.headers.get('retry-after') : null;
  let message = '';
  try {
    const payload = await res.json();
    if (payload && typeof payload.message === 'string') message = payload.message.trim().slice(0, 300);
  } catch {}
  const limited = res.status === 429 || remaining === '0' || Boolean(retryAfter) || /rate limit|secondary rate/i.test(message);
  return Object.assign(
    { success: false, status: limited ? 'rate_limited' : 'forbidden', repository: owner + '/' + repo, number, httpStatus: res.status, source: res.url || fallbackUrl },
    reset ? { rateLimitReset: reset } : null,
    retryAfter ? { retryAfter } : null,
    message ? { message } : null
  );
};
if (issueRes.status === 403 || issueRes.status === 429) {
  return await classifyAccessError(issueRes, issueUrl);
}
if (commentsRes.status === 403 || commentsRes.status === 429) {
  return await classifyAccessError(commentsRes, commentsUrl);
}
if (issueRes.status === 404) {
  return { success: false, status: 'not_found', repository: owner + '/' + repo, number, httpStatus: 404, source: issueRes.url || issueUrl };
}
if (!issueRes.ok) {
  return { success: false, status: 'http_error', repository: owner + '/' + repo, number, httpStatus: issueRes.status, source: issueRes.url || issueUrl };
}
if (!commentsRes.ok) {
  return { success: false, status: 'http_error', repository: owner + '/' + repo, number, httpStatus: commentsRes.status, source: commentsRes.url || commentsUrl };
}
let issueData;
let commentsData;
try {
  issueData = await issueRes.json();
  commentsData = await commentsRes.json();
} catch {
  return { success: false, status: 'invalid_json', repository: owner + '/' + repo, number, source: issueRes.url || issueUrl };
}
const title = String((issueData && issueData.title) || '').trim();
const page = String((issueData && issueData.html_url) || '').trim();
if (!title || !/^https:\/\/github\.com\/.+\/(?:issues|pull)\/\d+/.test(page) || !Array.isArray(commentsData)) {
  return { success: false, status: 'schema_changed', repository: owner + '/' + repo, number, source: issueRes.url || issueUrl };
}
const comments = commentsData.slice(0, limit).map(comment => ({
  author: String((comment && comment.user && comment.user.login) || '').trim(),
  createdAt: String((comment && comment.created_at) || '').trim(),
  url: String((comment && comment.html_url) || page).trim(),
  body: String((comment && comment.body) || '').trim().slice(0, 2000)
}));
return {
  success: true,
  status: 'ok',
  issue: {
    number: Math.max(1, Math.floor(Number(issueData.number) || number)),
    title,
    state: String(issueData.state || '').trim(),
    isPullRequest: Boolean(issueData.pull_request),
    author: String((issueData.user && issueData.user.login) || '').trim(),
    url: page,
    createdAt: String(issueData.created_at || '').trim(),
    updatedAt: String(issueData.updated_at || '').trim(),
    labels: Array.isArray(issueData.labels) ? issueData.labels.map(label => typeof label === 'string' ? label : String((label && label.name) || '')).filter(Boolean).slice(0, 15) : [],
    body: String(issueData.body || '').trim().slice(0, 6000),
    commentsCount: Math.max(comments.length, Math.floor(Number(issueData.comments) || 0))
  },
  comments,
  sources: {
    api: issueRes.url || issueUrl,
    commentsApi: commentsRes.url || commentsUrl,
    page
  }
};
